      },
      {
        name: 'Nested-1.3',
        description: 'Nested item #1.2',
        children: [
          { name: 'Nested-1.3.1', description: 'Nested item #1.3.1' },
          { name: 'Nested-1.3.2', description: 'Nested item #1.3.2' },
        ],
      },
    ],
  },
  {
    name: 'Root-2',
    description: 'Root item #2',
    children: [
      {
        name: 'Nested-2.1',
        description: 'Nested item #2.1',
        children: [],
      },
      {
        name: 'Nested-2.2',
        description: 'Nested item #2.2',
        children: [],
      },
    ],
  },
  {
    name: 'Root-3',
    description: 'Root item #3',
    children: [],
  },
];

interface Permutation {
  title: string;
  items: Instance[];
  resizableColumns?: boolean;
  editableCells?: boolean;
  stickyColumns?: boolean;
  stripedRows?: boolean;
  wrapLines?: boolean;
  selectionType?: 'single' | 'multi';
  progressiveLoading?: boolean;
}

const permutations = createPermutations<Permutation>([
  {
    title: ['Deep nesting'],
    items: [itemsDeep],
    resizableColumns: [false],
    editableCells: [false],
    stickyColumns: [false],
    stripedRows: [false],
    wrapLines: [false],
